/** Physical taps, decoded cross-UID files and real Package Installer on disposable emulators. */
public final class FileOpenSmoke extends Instrumentation {
    private String phase="open";private MainActivity home;private View root;private Uri folder,linked;private final Map<String,byte[]> samples=new LinkedHashMap<>();
    @Override public void onCreate(Bundle args){if(args!=null)phase=args.getString("phase","open");start();}
    @Override public void onStart(){Bundle result=new Bundle();try{
        DesktopStore store=new DesktopStore(getTargetContext());store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).commit();getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
        check(StorageAccess.has(getTargetContext()),"Real shared-storage access is enabled");home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();
        folder=DocumentOps.createFolder(getTargetContext(),StorageAccess.document("Download"),"Nth-Open-"+SystemClock.uptimeMillis(),new DocumentOps.Cancel());
        byte[] apk=read(new FileInputStream("/sdcard/Download/Nth-Install-Probe.apk"));put(folder,"Install.APK",apk);put(folder,"Unselected.bin",new byte[]{1,2,3});navigate(folder,"Open test files");
        if(phase.equals("blocked")){
            progress("tapping APK with install-from-this-source disabled");check(!getTargetContext().getPackageManager().canRequestPackageInstalls(),"APK source is initially untrusted");tap("Install.APK",.5f);await(()->node("Settings")!=null||node("SETTINGS")!=null,"Android offers unknown-app source settings");shot("file-open-install-blocked.png");check(!shell("pm path com.nthexperience.desktop.installprobe").contains("package:"),"Blocked install does not install a package");systemClick("Cancel");
            result.putString("stream","PASS: a real APK tap reaches Android's unknown-app-source approval; denied access does not install a package.\n");
        }else{
            check(getTargetContext().getPackageManager().canRequestPackageInstalls(),"Android allows this test source");buildSamples();for(Map.Entry<String,byte[]> entry:samples.entrySet())put(folder,entry.getKey(),entry.getValue());put(folder,"Unknown.nthunknown",new byte[]{7,8,9});navigate(folder,"Open test files");
            progress("physically tapping native TXT, JSON, PNG, JPG, PDF, WAV, MP4 and ZIP files");int i=0;for(String name:samples.keySet()){openAndCheck(name,new float[]{.12f,.5f,.88f}[i++%3]);}
            progress("checking selection can be exited after deselecting its last item");hold("Text.txt");click("Select");tap("Text.txt",.5f);await(()->find("Done selecting files")!=null,"Done selecting stays visible with zero selected files");tap("Done selecting files",.5f);openAndCheck("Text.txt",.5f);
            progress("checking Open with shares the same MIME and read-grant handling");clearReport();hold("Photo.JPG");click("Open with…");checkReport("Photo.JPG");
            tap("Unknown.nthunknown",.5f);await(()->node("Cannot open file")!=null,"Unsupported files show an explanation");shot("file-open-unsupported.png");systemClick("OK");
            progress("installing a real APK through Android's Package Installer");install();
            progress("checking linked SAF files with generic provider MIME types");shell("am start -n com.nthexperience.desktop.fixture/.GrantActivity --ez reset true");Uri tree=DocumentsContract.buildTreeDocumentUri("com.nthexperience.desktop.fixture.documents","root:");Uri providerRoot=DocumentsContract.buildDocumentUriUsingTree(tree,"root:");await(()->{try{DocumentOps.stat(getTargetContext(),providerRoot,new DocumentOps.Cancel());return true;}catch(Exception ex){return false;}},"Fixture folder is granted");linked=DocumentOps.createFolder(getTargetContext(),providerRoot,"Open types",new DocumentOps.Cancel());for(Map.Entry<String,byte[]> entry:samples.entrySet())put(linked,entry.getKey(),entry.getValue());put(linked,"Unselected.bin",new byte[]{4});put(linked,"Install.APK",apk);navigate(linked,"Linked open tests");for(String name:samples.keySet())openAndCheck(name,.5f);
            shell("pm uninstall com.nthexperience.desktop.installprobe");install();
            check(FileLaunch.mime("PACKAGE.APK","application/octet-stream").equals(FileLaunch.APK),"Uppercase APK names resolve correctly");check(FileLaunch.mime("plain.pdf","application/octet-stream").equals("application/pdf"),"Generic provider types use the filename");
            result.putString("stream","PASS: physical icon/title/row taps open and decode native and linked TXT/JSON/PNG/JPG/PDF/WAV/MP4/ZIP files in a separate app UID with exact bytes, read-only selected-file grants; Open with and zero-item selection exit; unsupported-file explanation; real native and SAF APK installs through Android's installer.\n");
        }
        cleanup();finish(Activity.RESULT_OK,result);
    }catch(Throwable ex){try{shot("file-open-failure.png");try(FileOutputStream out=getTargetContext().openFileOutput("file-open-tree.txt",0)){StringBuilder tree=new StringBuilder();dump(getUiAutomation().getRootInActiveWindow(),tree,0);out.write(tree.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}catch(Exception ignored){}StringWriter trace=new StringWriter();ex.printStackTrace(new PrintWriter(trace));result.putString("stream","FAIL: "+trace);cleanup();finish(Activity.RESULT_CANCELED,result);}}
    private void buildSamples()throws Exception{
        samples.put("Text.txt","Nth opening test — café".getBytes(java.nio.charset.StandardCharsets.UTF_8));samples.put("Data.json","{\"nth\":true}".getBytes(java.nio.charset.StandardCharsets.UTF_8));
        Bitmap image=Bitmap.createBitmap(80,60,Bitmap.Config.ARGB_8888);image.eraseColor(0xff4b8eaf);for(String name:new String[]{"Picture.png","Photo.JPG"}){ByteArrayOutputStream out=new ByteArrayOutputStream();image.compress(name.endsWith("png")?Bitmap.CompressFormat.PNG:Bitmap.CompressFormat.JPEG,95,out);samples.put(name,out.toByteArray());}image.recycle();
        PdfDocument pdf=new PdfDocument();PdfDocument.Page page=pdf.startPage(new PdfDocument.PageInfo.Builder(200,200,1).create());Paint paint=new Paint();paint.setColor(Color.BLUE);page.getCanvas().drawText("Nth PDF",20,50,paint);pdf.finishPage(page);ByteArrayOutputStream out=new ByteArrayOutputStream();pdf.writeTo(out);pdf.close();samples.put("Document.pdf",out.toByteArray());
        int count=8000;ByteBuffer wav=ByteBuffer.allocate(44+count*2).order(ByteOrder.LITTLE_ENDIAN);wav.put("RIFF".getBytes()).putInt(36+count*2).put("WAVEfmt ".getBytes()).putInt(16).putShort((short)1).putShort((short)1).putInt(8000).putInt(16000).putShort((short)2).putShort((short)16).put("data".getBytes()).putInt(count*2);for(int i=0;i<count;i++)wav.putShort((short)(Math.sin(i*2*Math.PI*440/8000)*1000));samples.put("Sound.wav",wav.array());try(InputStream video=getContext().getAssets().open("sample.mp4")){samples.put("Video.mp4",read(video));}
        out=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(out)){zip.putNextEntry(new ZipEntry("inside.txt"));zip.write("Nth archive".getBytes());zip.closeEntry();}samples.put("Archive.zip",out.toByteArray());
    }
    private void put(Uri parent,String name,byte[] bytes)throws Exception{Uri uri=DocumentsContract.createDocument(getTargetContext().getContentResolver(),parent,FileLaunch.mime(name,null),name);check(uri!=null,"Fixture created: "+name);try(OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){out.write(bytes);}}
    private VistaExplorer explorer(){return (VistaExplorer)find(root,v->v instanceof VistaExplorer);}
    private void navigate(Uri directory,String name)throws Exception{shell("am start -W -n "+new ComponentName(getTargetContext(),MainActivity.class).flattenToString());await(()->home.hasWindowFocus(),"Desktop has focus before navigating after an external grant");ui(()->home.open("@computer"));await(()->explorer()!=null,"Explorer is attached before navigation");Uri tree=DocumentsContract.buildTreeDocumentUri(directory.getAuthority(),StorageAccess.ours(directory)?"primary:":"root:");String page=DocumentFolders.rootPage(tree.toString(),name);String id=DocumentsContract.getDocumentId(directory);DocumentFolders.Item item=new DocumentFolders.Item(id,name,DocumentsContract.Document.MIME_TYPE_DIR,0,0);String target=DocumentFolders.childPage(page,item);ui(()->{explorer().refreshFiles();explorer().navigate(target);});await(()->find("Install.APK")!=null,"Folder files load");Thread.sleep(250);}
    private void openAndCheck(String name,float point)throws Exception{progress("opening "+name);clearReport();if(MediaLibrary.entry(StorageAccess.document("Download/"+name),name,null)!=null){hold(name);click("Open with…");checkReport(name);return;}tap(name,point);if(PhotoImage.picture(name,FileLaunch.mime(name,null))){await(()->find(root,v->v instanceof PhotoGallery)!=null,"Picture opens in Photo Gallery");PhotoGallery gallery=(PhotoGallery)find(root,v->v instanceof PhotoGallery);await(gallery::ready,"Gallery decodes "+name);check(gallery.canvas.pixelWidth()==80,"Gallery displays the real image dimensions");ui(gallery::back);await(()->find(name)!=null,"Back restores Explorer");hold(name);click("Open with…");}checkReport(name);}
    private void checkReport(String name)throws Exception{long end=SystemClock.uptimeMillis()+15000;JSONObject report=null;long lastChoice=0;while(SystemClock.uptimeMillis()<end){try{JSONObject value=new JSONObject(shell("run-as "+getContext().getPackageName()+" cat files/file-open-result.json"));if(name.equals(value.optString("name"))){report=value;break;}if(value.has("error"))throw new AssertionError(value.toString());}catch(JSONException ignored){}if(node("Nth file test viewer")!=null&&SystemClock.uptimeMillis()-lastChoice>1000){getUiAutomation().waitForIdle(200,3000);if(node("Nth file test viewer")!=null)systemClick("Nth file test viewer");lastChoice=SystemClock.uptimeMillis();}AccessibilityNodeInfo once=node("Just once");if(once!=null&&once.isEnabled()){while(once!=null&&!once.isClickable())once=once.getParent();if(once!=null)once.performAction(AccessibilityNodeInfo.ACTION_CLICK);}Thread.sleep(100);}check(report!=null,"A real tap delivered "+name+" to its viewer");check(report.getBoolean("decoded"),"Viewer decoded "+name);check(report.getString("mime").equals(FileLaunch.mime(name,null)),"Correct type for "+name+": "+report);check(report.getString("sha256").equals(digest(samples.get(name))),"Viewer receives exact bytes");check(report.getBoolean("writeDenied")&&report.getBoolean("unselectedDenied"),"Viewer gets only read access to the selected file");await(()->home.hasWindowFocus(),"Viewer returns to Explorer");}
    private void install()throws Exception{tap("Install.APK",.5f);await(()->node("Install")!=null,"Android shows an Install confirmation");shot("file-open-install.png");systemClick("Install");await(()->shellQuiet("pm path com.nthexperience.desktop.installprobe").contains("package:"),"Package Installer actually installs the probe");await(()->node("Done")!=null,"Android reports installation completed");shot("file-open-installed.png");systemClick("Done");await(()->home.hasWindowFocus(),"Installer returns to Explorer");}
    private void clearReport()throws Exception{shell("run-as "+getContext().getPackageName()+" rm -f files/file-open-result.json");}
    private void cleanup(){try{shell("pm uninstall com.nthexperience.desktop.installprobe");if(folder!=null)DocumentOps.delete(getTargetContext(),Collections.singletonList(new DocumentOps.Ref(folder,StorageAccess.document("Download"),DocumentOps.stat(getTargetContext(),folder,new DocumentOps.Cancel()))),new DocumentOps.Cancel());if(linked!=null)DocumentOps.delete(getTargetContext(),Collections.singletonList(new DocumentOps.Ref(linked,null,DocumentOps.stat(getTargetContext(),linked,new DocumentOps.Cancel()))),new DocumentOps.Cancel());}catch(Exception ignored){}}
    private View find(String text){return find(root,v->text.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()));}
    private View find(View v,Predicate<View> match){if(v==null||!v.isShown())return null;if(match.test(v))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View result=find(((ViewGroup)v).getChildAt(i),match);if(result!=null)return result;}return null;}
    private void ensureVisible(String name)throws Exception{ListView list=(ListView)find(root,v->v instanceof ListView&&"Folder contents".contentEquals(v.getContentDescription()==null?"":v.getContentDescription()));if(list!=null)for(int i=0;i<list.getAdapter().getCount();i++){Object item=list.getAdapter().getItem(i);if(item instanceof DocumentFolders.Item&&name.equals(((DocumentFolders.Item)item).name)){int at=i;ui(()->list.setSelection(at));Thread.sleep(200);break;}}}
    private void click(String label)throws Exception{View view=find(label);if(view!=null)ui(view::performClick);else systemClick(label);}
    private void tap(String name,float x)throws Exception{ensureVisible(name);await(()->find(name)!=null,"File/control is visible: "+name);View view=find(name);int[] at=new int[2];ui(()->view.getLocationOnScreen(at));long down=SystemClock.uptimeMillis();touch(down,MotionEvent.ACTION_DOWN,at[0]+view.getWidth()*x,at[1]+view.getHeight()/2f);Thread.sleep(70);touch(down,MotionEvent.ACTION_UP,at[0]+view.getWidth()*x,at[1]+view.getHeight()/2f);Thread.sleep(160);}
    private void hold(String name)throws Exception{ensureVisible(name);View view=find(name);check(view!=null,"File is visible: "+name);int[] at=new int[2];view.getLocationOnScreen(at);long down=SystemClock.uptimeMillis();touch(down,MotionEvent.ACTION_DOWN,at[0]+view.getWidth()/2f,at[1]+view.getHeight()/2f);Thread.sleep(700);touch(down,MotionEvent.ACTION_UP,at[0]+view.getWidth()/2f,at[1]+view.getHeight()/2f);await(()->node("File context menu")!=null,"Real long press opens file menu");}
    private void touch(long down,int action,float x,float y){MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(event,true),"Physical touch accepted");event.recycle();}
    private AccessibilityNodeInfo node(String text){return node(getUiAutomation().getRootInActiveWindow(),text);}
    private AccessibilityNodeInfo node(AccessibilityNodeInfo n,String text){if(n==null)return null;if(text.equalsIgnoreCase(n.getText()==null?"":n.getText().toString())||text.contentEquals(n.getContentDescription()==null?"":n.getContentDescription()))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo found=node(n.getChild(i),text);if(found!=null)return found;}return null;}
    private void systemClick(String text)throws Exception{await(()->{AccessibilityNodeInfo n=node(text);return n!=null&&n.isEnabled();},"System control: "+text);AccessibilityNodeInfo n=node(text);android.graphics.Rect bounds=new android.graphics.Rect();n.getBoundsInScreen(bounds);check(!bounds.isEmpty(),"System action has touch bounds: "+text);long down=SystemClock.uptimeMillis();touch(down,MotionEvent.ACTION_DOWN,bounds.exactCenterX(),bounds.exactCenterY());Thread.sleep(70);touch(down,MotionEvent.ACTION_UP,bounds.exactCenterX(),bounds.exactCenterY());Thread.sleep(250);}
    private void ui(Runnable action){runOnMainSync(action);try{Thread.sleep(70);}catch(InterruptedException ex){throw new AssertionError(ex);}}
    private void await(BooleanSupplier ready,String message)throws Exception{long end=SystemClock.uptimeMillis()+15000;while(SystemClock.uptimeMillis()<end){if(ready.getAsBoolean())return;Thread.sleep(100);}throw new AssertionError(message);}
    private String shellQuiet(String value){try{return shell(value);}catch(Exception ex){return "";}}
    private String shell(String command)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){return new String(read(in),java.nio.charset.StandardCharsets.UTF_8);}}
    private static byte[] read(InputStream in)throws IOException{try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int n;while((n=input.read(buffer))!=-1)out.write(buffer,0,n);return out.toByteArray();}}
    private static String digest(byte[] bytes)throws Exception{StringBuilder out=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
    private void shot(String name)throws Exception{Bitmap bitmap=getUiAutomation().takeScreenshot();check(bitmap!=null,"Screenshot available");try(FileOutputStream out=getTargetContext().openFileOutput(name,0)){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}finally{bitmap.recycle();}}
    private void dump(AccessibilityNodeInfo n,StringBuilder out,int depth){if(n==null||depth>24)return;out.append(depth).append(' ').append(n.getPackageName()).append(' ').append(n.getText()).append(' ').append(n.getContentDescription()).append('\n');for(int i=0;i<n.getChildCount();i++)dump(n.getChild(i),out,depth+1);}
    private void progress(String message){Bundle out=new Bundle();out.putString("stream","CHECK: "+message+"\n");sendStatus(1,out);}
    private static void check(boolean okay,String message){if(!okay)throw new AssertionError(message);}
}
